-- ============================================================================
-- 17 neue CRA-Kontrollen (CRA-26..33): Risikobewertung Art.13(2-4), Support-
-- zeitraum/Enddatum 13(8-11)/(19), DoC/CE Annex V + Art.28/30, Nutzerinfo
-- Annex II, Komponenten-Sorgfalt 13(5), schwerer Vorfall Art.14(3-7), Opt-out-
-- Logging, Security/Feature-Trennung, Korrekturmassnahmen 13(21). Idempotent.
-- ============================================================================
BEGIN;

ON CONFLICT (framework,id) DO UPDATE
  SET req_de=EXCLUDED.req_de, req_en=EXCLUDED.req_en, meta=EXCLUDED.meta;

-- Verknuepfungen Kontrolle->Risiko stehen in cra_risk_texts.sql (Schritt 3i),
-- NACH dem Anlegen der Risiken. Hier standen sie vorher auch — vor den
-- Risiken: der Fremdschluessel control_risk_risk_id_fkey liess die ganze
-- Transaktion scheitern, und 3i scheiterte danach am fehlenden Control.
-- Beide Dateien liefen im Deploy (|| true) still ins Leere; lokal
-- nachgestellt am 19.09.2026. Die 17 Verknuepfungen sind in 3i vollstaendig
-- enthalten (geprueft: Teilmenge der 83).

COMMIT;
